#include <list>

#define MAX_TRICKS_PER_SERIES 64
#define GAP_NUM 173
#define GAME_MODE_CAREER 0
#define BEACH_INDOOR 12

class entity;
class kellyslater_controller {
public:
    bool IsAIPlayer();
};

class SpecialMeter {
public:
    void Increase(float);
};

class IGOTutorialManager {
public:
    void SetCurrentGap(int);
};

class IGOFrontEnd {
    char padding[0x480];
public:
    IGOTutorialManager *GetTutorialManager()
    {
        return *(IGOTutorialManager **)((char *)this + 0x480);
    }
    void OnTrickChange(int, bool);
};

class FEManager {
public:
    IGOFrontEnd *IGO;
};

class game {
    char padding[0x74];
    int mode;
    char padding2[0x1b0];
    int beach;
public:
    int get_game_mode() const { return mode; }
    int get_beach_id() const { return beach; }
};

class world_dynamics_system {
    char padding[0xf8];
public:
    kellyslater_controller *controllers[4];
};

enum EVENT {
    EVT_TRICK_FACE_BEGIN = 4,
    EVT_TRICK_FACE_END = 5
};

class EventManager {
public:
    void DispatchEvent(EVENT, int, int = 0);
};

enum EventType {
    SS_GAP = 99
};

class SoundScriptManager {
public:
    int playEvent(EventType, entity * = 0, float = 0.0f);
};

class ScoringManager {
public:
    struct LevelTrick {
        int numLandings;
    };

    class Trick {
    public:
        enum TYPE { TYPE_TRICK, TYPE_GAP };
        TYPE type;
        int index;
        int flags;
        float time;
        int numSpins;
        float mouthDist;
        float lipDist;
        int repetitions;
        Trick();
    };

    typedef std::list<Trick> TrickList;

    class Series {
    public:
        LevelTrick *levelTricks;
        TrickList tricks;
        int numSpins;
        int landing;
        int flags;
        Series();
    };

    typedef std::list<Series> SeriesList;

    class Chain {
        char padding[8];
    public:
        SeriesList series;
        float GetSickness() const;
    };

private:
    char padding0[12];
    int playerIdx;
    SpecialMeter *specialMeter;
    char padding1[408];
    Chain chain;
    char padding2[36];
    float mouthDist;

public:
    void AddGap(int gapIdx);
};

extern game *g_game_ptr;
extern world_dynamics_system *g_world_ptr;
extern FEManager frontendmanager;
extern EventManager g_eventManager;
extern SoundScriptManager *sound_manager;

__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ g_world_ptr, 0x00431A8C");
__asm__(".equ frontendmanager, 0x003E7728");
__asm__(".equ g_eventManager, 0x0046DA20");
__asm__(".equ sound_manager, 0x0046B4A0");
