__asm__(".equ Increase__12SpecialMeterf, 0x00250FB8");
__asm__(".equ SetCurrentGap__18IGOTutorialManageri, 0x0015A0B8");
__asm__(".equ OnTrickChange__11IGOFrontEndib, 0x0017BD08");
__asm__(".equ DispatchEvent__12EventManager5EVENTii, 0x00349AB0");
__asm__(".equ IsAIPlayer__22kellyslater_controller, 0x00224D78");
